target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite
mkdir -p /tmp/fact
./collatz_tests spectral-gaps --moduli 9,27,81 --tilts 0,1 --L 48 --R 6 --bmax 20 --char-cap 0 --height-mode factored --output-dir /tmp/fact 2>&1 | tail -1
echo "=== FACTORED coupling: quadratic char (k=phi/2) gap_ratio, and uniform kappa_Q=1-max ==="
grep -v '^#' /tmp/fact/spectral_gaps.csv | grep -v '^Q,L' | awk -F, '
  $6!="trivial"{
    Q=$1; s=$5; k=$7; gr=$17;
    if(!((Q,s) in mx)||gr>mx[Q,s])mx[Q,s]=gr;
    isquad=(($1==9&&k==3)||($1==27&&k==9)||($1==81&&k==27));
    if(isquad) printf "  Q=%-3s s=%s quadratic-char gap_ratio_units=%.4f\n",Q,s,gr
  }
  END{ print "  --- uniform kappa_Q = 1 - max_chi ratio ---";
    for(key in mx){ split(key,p,SUBSEP); printf "  Q=%-3s s=%s kappa_Q=%.4f\n",p[1],p[2],1-mx[key] } }' | sort
